package thanh.toan.duan1.fragment;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.localbroadcastmanager.content.LocalBroadcastManager;

import java.util.HashMap;
import java.util.Map;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import thanh.toan.duan1.R;
import thanh.toan.duan1.api.ApiService;
import thanh.toan.duan1.api.apiProfile;
import thanh.toan.duan1.model.User;
import thanh.toan.duan1.ui.LoginActivity;

public class EditProfileFragment extends Fragment {

    private EditText edtFullName, edtEmail, edtPhone, edtAddress, edtPassword;
    private Button btnSave;
    private User currentUser;

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_edit_profile, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        edtFullName = view.findViewById(R.id.edt_full_name);
        edtEmail = view.findViewById(R.id.edt_email);
        edtPhone = view.findViewById(R.id.edt_phone);
        edtAddress = view.findViewById(R.id.edt_address);
        edtPassword = view.findViewById(R.id.edt_password);
        btnSave = view.findViewById(R.id.btn_save_profile);

        loadProfile();

        btnSave.setOnClickListener(v -> saveProfile());
    }

    private void loadProfile() {
        apiProfile api = ApiService.getApi(requireContext()).create(apiProfile.class);
        api.getUserProfile().enqueue(new Callback<User>() {
            @Override
            public void onResponse(Call<User> call, Response<User> response) {
                if (response.isSuccessful() && response.body() != null) {
                    currentUser = response.body();
                    edtFullName.setText(currentUser.getFullName() != null ? currentUser.getFullName() : "");
                    edtEmail.setText(currentUser.getEmail() != null ? currentUser.getEmail() : "");
                    edtPhone.setText(currentUser.getPhone() != null ? currentUser.getPhone() : "");
                    edtAddress.setText(currentUser.getAddress() != null ? currentUser.getAddress() : "");
                } else {
                    Toast.makeText(requireContext(), "Cannot load profile", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<User> call, Throwable t) {
                Toast.makeText(requireContext(), "Network error: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void saveProfile() {
        String fullName = edtFullName.getText().toString().trim();
        String email = edtEmail.getText().toString().trim();
        String phone = edtPhone.getText().toString().trim();
        String address = edtAddress.getText().toString().trim();
        String password = edtPassword.getText().toString();

        Map<String, Object> body = new HashMap<>();
        if (!fullName.isEmpty() && (currentUser == null || !fullName.equals(currentUser.getFullName()))) body.put("fullName", fullName);
        if (!phone.isEmpty() && (currentUser == null || !phone.equals(currentUser.getPhone()))) body.put("phone", phone);
        if (!address.isEmpty() && (currentUser == null || !address.equals(currentUser.getAddress()))) body.put("address", address);
        if (!email.isEmpty() && (currentUser == null || !email.equalsIgnoreCase(currentUser.getEmail()))) body.put("email", email.toLowerCase());
        if (!password.isEmpty()) {
            if (password.length() < 6) {
                Toast.makeText(requireContext(), "Password must be at least 6 characters", Toast.LENGTH_SHORT).show();
                return;
            }
            body.put("password", password);
        }

        if (body.isEmpty()) {
            Toast.makeText(requireContext(), "No changes to save", Toast.LENGTH_SHORT).show();
            return;
        }

        apiProfile api = ApiService.getApi(requireContext()).create(apiProfile.class);
        api.updateUserProfile(body).enqueue(new Callback<User>() {
            @Override
            public void onResponse(Call<User> call, Response<User> response) {
                if (response.isSuccessful() && response.body() != null) {
                    // notify other fragments
                    LocalBroadcastManager.getInstance(requireContext()).sendBroadcast(new Intent("profile_updated"));
                    Toast.makeText(requireContext(), "Profile updated", Toast.LENGTH_SHORT).show();

                    // if password changed, force re-login
                    if (body.containsKey("password")) {
                        SharedPreferences prefs = requireContext().getSharedPreferences("MyAppPrefs", Context.MODE_PRIVATE);
                        prefs.edit().remove("token").apply();
                        Intent intent = new Intent(getActivity(), LoginActivity.class);
                        startActivity(intent);
                        requireActivity().finish();
                    } else {
                        // pop back to previous fragment
                        requireActivity().getSupportFragmentManager().popBackStack();
                    }
                } else {
                    String msg = "Update failed";
                    try {
                        if (response.errorBody() != null) msg = response.errorBody().string();
                    } catch (Exception ignored) {}
                    Toast.makeText(requireContext(), msg, Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<User> call, Throwable t) {
                Toast.makeText(requireContext(), "Network error: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }
}

package thanh.toan.duan1.fragment;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.localbroadcastmanager.content.LocalBroadcastManager;

import java.util.HashMap;
import java.util.Map;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import thanh.toan.duan1.R;
import thanh.toan.duan1.api.ApiService;
import thanh.toan.duan1.api.apiProfile;
import thanh.toan.duan1.model.User;
import thanh.toan.duan1.ui.LoginActivity;

public class EditProfileFragment extends Fragment {

    private EditText edtFullName, edtEmail, edtPhone, edtAddress, edtPassword;
    private Button btnSave;
    private User currentUser;

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_edit_profile, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        edtFullName = view.findViewById(R.id.edt_full_name);
        edtEmail = view.findViewById(R.id.edt_email);
        edtPhone = view.findViewById(R.id.edt_phone);
        edtAddress = view.findViewById(R.id.edt_address);
        edtPassword = view.findViewById(R.id.edt_password);
        btnSave = view.findViewById(R.id.btn_save_profile);

        loadProfile();

        btnSave.setOnClickListener(v -> saveProfile());
    }

    private void loadProfile() {
        apiProfile api = ApiService.getApi(requireContext()).create(apiProfile.class);
        api.getUserProfile().enqueue(new Callback<User>() {
            @Override
            public void onResponse(Call<User> call, Response<User> response) {
                if (response.isSuccessful() && response.body() != null) {
                    currentUser = response.body();
                    edtFullName.setText(currentUser.getFullName() != null ? currentUser.getFullName() : "");
                    edtEmail.setText(currentUser.getEmail() != null ? currentUser.getEmail() : "");
                    edtPhone.setText(currentUser.getPhone() != null ? currentUser.getPhone() : "");
                    edtAddress.setText(currentUser.getAddress() != null ? currentUser.getAddress() : "");
                } else {
                    Toast.makeText(requireContext(), "Cannot load profile", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<User> call, Throwable t) {
                Toast.makeText(requireContext(), "Network error: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void saveProfile() {
        String fullName = edtFullName.getText().toString().trim();
        String email = edtEmail.getText().toString().trim();
        String phone = edtPhone.getText().toString().trim();
        String address = edtAddress.getText().toString().trim();
        String password = edtPassword.getText().toString();

        Map<String, Object> body = new HashMap<>();
        if (!fullName.isEmpty() && (currentUser == null || !fullName.equals(currentUser.getFullName()))) body.put("fullName", fullName);
        if (!phone.isEmpty() && (currentUser == null || !phone.equals(currentUser.getPhone()))) body.put("phone", phone);
        if (!address.isEmpty() && (currentUser == null || !address.equals(currentUser.getAddress()))) body.put("address", address);
        if (!email.isEmpty() && (currentUser == null || !email.equalsIgnoreCase(currentUser.getEmail()))) body.put("email", email.toLowerCase());
        if (!password.isEmpty()) {
            if (password.length() < 6) {
                Toast.makeText(requireContext(), "Password must be at least 6 characters", Toast.LENGTH_SHORT).show();
                return;
            }
            body.put("password", password);
        }

        if (body.isEmpty()) {
            Toast.makeText(requireContext(), "No changes to save", Toast.LENGTH_SHORT).show();
            return;
        }

        apiProfile api = ApiService.getApi(requireContext()).create(apiProfile.class);
        api.updateUserProfile(body).enqueue(new Callback<User>() {
            @Override
            public void onResponse(Call<User> call, Response<User> response) {
                if (response.isSuccessful() && response.body() != null) {
                    // notify other fragments
                    LocalBroadcastManager.getInstance(requireContext()).sendBroadcast(new Intent("profile_updated"));
                    Toast.makeText(requireContext(), "Profile updated", Toast.LENGTH_SHORT).show();

                    // if password changed, force re-login
                    if (body.containsKey("password")) {
                        SharedPreferences prefs = requireContext().getSharedPreferences("MyAppPrefs", Context.MODE_PRIVATE);
                        // remove token and any stored remembered password so auto-login won't retry with old password
                        SharedPreferences.Editor editor = prefs.edit();
                        editor.remove("token");
                        editor.remove("password");
                        editor.remove("email");
                        editor.remove("remember");
                        editor.apply();
                        Intent intent = new Intent(getActivity(), LoginActivity.class);
                        startActivity(intent);
                        requireActivity().finish();
                    } else {
                        // pop back to previous fragment
                        requireActivity().getSupportFragmentManager().popBackStack();
                    }
                } else {
                    String msg = "Update failed";
                    try {
                        if (response.errorBody() != null) msg = response.errorBody().string();
                    } catch (Exception ignored) {}
                    Toast.makeText(requireContext(), msg, Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<User> call, Throwable t) {
                Toast.makeText(requireContext(), "Network error: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }
}
